/** Settings that control how available booking times are displayed to customers. */
export interface TimeSlotsConfiguration {
  /**
   * Time slots configuration ID.
   * @format GUID
   * @readonly
   */
  id?: string | null;
  /**
   * Revision number, which increments by 1 each time the time slots configuration is updated.
   * To prevent conflicting changes, the current revision must be passed when updating the time slots configuration.
   *
   * Ignored when creating a time slots configuration.
   * @readonly
   */
  revision?: string | null;
  /**
   * Date and time the time slots configuration was created.
   * @readonly
   */
  createdDate?: Date | null;
  /**
   * Date and time the time slots configuration was last updated.
   * @readonly
   */
  updatedDate?: Date | null;
  /** Time zone display settings. */
  displayTimeZone?: DisplayTimeZone;
  /** Staff selection settings that control how staff members are assigned to bookings. */
  staffSelection?: StaffSelection;
  /** Time interval settings that control how available time slots are divided. */
  splitInterval?: SplitInterval;
  /**
   * App that owns this configuration. Set by the Bookings platform when the time slots configuration is created via [Provision Bookings Platform](https://dev.wix.com/docs/api-reference/business-solutions/bookings/bookings-platform/bookings-platform-provisioner/provision-bookings-platform).
   * @format GUID
   */
  appId?: string;
  /**
   * Custom field data for the time slots configuration object.
   *
   * [Extended fields](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/backend-extensions/schema-plugins/about-schema-plugin-extensions) must be configured in the app dashboard before they can be accessed with API calls.
   */
  extendedFields?: ExtendedFields;
}

export interface DisplayTimeZone {
  /**
   * Whether the customer can change the time zone when booking or viewing an existing booking.
   *
   * Default: `true`
   */
  customerCanChange?: boolean | null;
  /**
   * Time zone used to display available times, either based on the business's or customer's location.
   *
   * Default: `BUSINESS_TIME_ZONE`
   */
  basedOn?: BasedOnWithLiterals;
  /**
   * The business's time zone, in IANA time zone format (for example, `America/New_York`).
   * Derived from the site's business properties.
   * @maxLength 255
   * @readonly
   */
  timeZone?: string | null;
}

export enum BasedOn {
  /** Display time zone is based on the business's location. */
  BUSINESS_TIME_ZONE = 'BUSINESS_TIME_ZONE',
  /** Display time zone is based on the customer's location. */
  CUSTOMER_TIME_ZONE = 'CUSTOMER_TIME_ZONE',
}

/** @enumType */
export type BasedOnWithLiterals =
  | BasedOn
  | 'BUSINESS_TIME_ZONE'
  | 'CUSTOMER_TIME_ZONE';

export interface StaffSelection {
  /** Staff selection strategy. */
  strategy?: StrategyWithLiterals;
  /**
   * Whether customers can narrow the staff pool to a gender instead of picking a specific staff member.
   * Only meaningful when `strategy` is `CUSTOMER_MAY_CHOOSE`.
   *
   * Requires staff members' gender to be publicly accessible, controlled by `gender_publicly_accessible`
   * in the staff member settings. While that setting is `false`, a customer's request to narrow the staff
   * pool by gender fails with an error.
   *
   * Default: `false`
   */
  allowGenderSelection?: boolean | null;
}

export enum Strategy {
  /** Customer must explicitly select a staff member. Booking fails if no staff is selected. */
  CUSTOMER_MUST_CHOOSE = 'CUSTOMER_MUST_CHOOSE',
  /** Customer can select a specific staff member or choose "any available". */
  CUSTOMER_MAY_CHOOSE = 'CUSTOMER_MAY_CHOOSE',
  /** Staff selection is hidden from the customer. The system auto-assigns a staff member. */
  CUSTOMER_CANNOT_CHOOSE = 'CUSTOMER_CANNOT_CHOOSE',
}

/** @enumType */
export type StrategyWithLiterals =
  | Strategy
  | 'CUSTOMER_MUST_CHOOSE'
  | 'CUSTOMER_MAY_CHOOSE'
  | 'CUSTOMER_CANNOT_CHOOSE';

/** Interval between available slot start times. For example, 15 minutes to display available slots at `3:00`, `3:15`, and `3:30` PM. */
export interface SplitInterval {
  /**
   * Whether the slot duration is used as the interval value.
   * - `true`: The interval is identical to the service's slot duration.
   * - `false`: The interval is a fixed number of minutes specified in `valueInMinutes`.
   *
   * Default: `false`
   */
  sameAsDuration?: boolean | null;
  /**
   * Number of minutes between available slot start times.
   * Ignored when `sameAsDuration: true`.
   *
   * Default: `30`
   */
  valueInMinutes?: number | null;
}

export interface ExtendedFields {
  /**
   * Extended field data. Each key corresponds to the namespace of the app that created the extended fields.
   * The value of each key is structured according to the schema defined when the extended fields were configured.
   *
   * You can only access fields for which you have the appropriate permissions.
   *
   * Learn more about [extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields).
   */
  namespaces?: Record<string, Record<string, any>>;
}

